public int getRealPort() {
    if (StringUtils.isEmpty(getPort())) {
        return DevicesInteracter.PORT_TCP_DEVICE;
    }
    return Integer.decode("0x" + getPort()).intValue() >> 2;
}

public static byte[] makeSendDataBLE(byte b, byte[] bArr, BluetoothDeviceModel bluetoothDeviceModel) {
    try {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        byteArrayOutputStream.write(236);
        byteArrayOutputStream.write(ComposerKt.referenceKey);
        byteArrayOutputStream.write(b);
        byteArrayOutputStream.write(StringUtils.shortToByteLittle(bArr != null ? (short) bArr.length : (short) 0));
        if (bArr != null && bArr.length != 0) {
            byteArrayOutputStream.write(bArr);
        }
        if ("a33".equalsIgnoreCase(bluetoothDeviceModel.getFirmwareVersion())) {
            byteArrayOutputStream.write(38);
        } else {
            byteArrayOutputStream.write(251);
        }
        byte[] byteArray = byteArrayOutputStream.toByteArray();
        byteArrayOutputStream.close();
        return byteArray;
    } catch (IOException e) {
        e.printStackTrace();
        return null;
    }
}

public byte[] makeSendParams(byte[] bArr, String str) {
    try {
        if (this.seqNo > 255) {
            this.seqNo = (byte) 0;
        }
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        byteArrayOutputStream.write(163);
        byteArrayOutputStream.write(191);
        byteArrayOutputStream.write(this.seqNo);
        byte[] bytes = str != null ? str.getBytes(StandardCharsets.UTF_8) : new byte[0];
        short length = (short) bytes.length;
        byteArrayOutputStream.write(StringUtils.shortToByteLittle(length));
        byteArrayOutputStream.write(bArr);
        if (bytes.length > 0) {
            byteArrayOutputStream.write(bytes);
        }
        byteArrayOutputStream.write(251);
        this.seqNo = (byte) (this.seqNo + 1);
        byte[] byteArray = byteArrayOutputStream.toByteArray();
        byteArrayOutputStream.close();
        if (byteArray.length >= 7) {
            StringBuilder sb = new StringBuilder();
            sb.append(!StringUtils.isEmpty(getName()) ? getName() : getIp());
            sb.append(" Send: ");
            sb.append(String.format("startTag:0x%02X%02X, seqNo:%02X, length:%02X%02X(%d), commandID:0x%02X%02X, data:\"%s\", endTag:0x%02X", Byte.valueOf(byteArray[0]), Byte.valueOf(byteArray[1]), Byte.valueOf(byteArray[2]), Byte.valueOf(byteArray[3]), Byte.valueOf(byteArray[4]), Short.valueOf(length), Byte.valueOf(byteArray[5]), Byte.valueOf(byteArray[6]), str, Byte.valueOf(byteArray[byteArray.length - 1])));
            LogUtils.debug(sb.toString());
            return byteArray;
        }
        LogUtils.debug("make send data: ".concat(new String(byteArray, StandardCharsets.UTF_8)));
        return byteArray;
    } catch (Exception e) {
        e.printStackTrace();
        return null;
    }
}
